     1→import {ChainConfig} from "@lodestar/config";
     2→import {
     3→  KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
     4→  KZG_COMMITMENTS_SUBTREE_INDEX,
     5→  NUMBER_OF_COLUMNS,
     6→} from "@lodestar/params";
     7→import {computeStartSlotAtEpoch, getBlockHeaderProposerSignatureSet} from "@lodestar/state-transition";
     8→import {Root, Slot, SubnetID, fulu, ssz} from "@lodestar/types";
     9→import {toRootHex, verifyMerkleBranch} from "@lodestar/utils";
    10→import {Metrics} from "../../metrics/metrics.js";
    11→import {kzg} from "../../util/kzg.js";
    12→import {
    13→  DataColumnSidecarErrorCode,
    14→  DataColumnSidecarGossipError,
    15→  DataColumnSidecarValidationError,
    16→} from "../errors/dataColumnSidecarError.js";
    17→import {GossipAction} from "../errors/gossipValidation.js";
    18→import {IBeaconChain} from "../interface.js";
    19→import {RegenCaller} from "../regen/interface.js";
    20→
    21→// SPEC FUNCTION
    22→// https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id
    23→export async function validateGossipDataColumnSidecar(
    24→  chain: IBeaconChain,
    25→  dataColumnSidecar: fulu.DataColumnSidecar,
    26→  gossipSubnet: SubnetID,
    27→  metrics: Metrics | null
    28→): Promise<void> {
    29→  const blockHeader = dataColumnSidecar.signedBlockHeader.message;
    30→
    31→  // 1) [REJECT] The sidecar is valid as verified by verify_data_column_sidecar
    32→  verifyDataColumnSidecar(dataColumnSidecar);
    33→
    34→  // 2) [REJECT] The sidecar is for the correct subnet -- i.e. compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id
    35→  if (computeSubnetForDataColumnSidecar(chain.config, dataColumnSidecar) !== gossipSubnet) {
    36→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    37→      code: DataColumnSidecarErrorCode.INVALID_SUBNET,
    38→      columnIdx: dataColumnSidecar.index,
    39→      gossipSubnet: gossipSubnet,
    40→    });
    41→  }
    42→
    43→  // 3) [IGNORE] The sidecar is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)
    44→  //             -- i.e. validate that sidecar.slot <= current_slot (a client MAY queue future blocks
    45→  //             for processing at the appropriate slot).
    46→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    47→  if (currentSlotWithGossipDisparity < blockHeader.slot) {
    48→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    49→      code: DataColumnSidecarErrorCode.FUTURE_SLOT,
    50→      currentSlot: currentSlotWithGossipDisparity,
    51→      blockSlot: blockHeader.slot,
    52→    });
    53→  }
    54→
    55→  // 4) [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
    56→  //             sidecar.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    57→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    58→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    59→  if (blockHeader.slot <= finalizedSlot) {
    60→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    61→      code: DataColumnSidecarErrorCode.WOULD_REVERT_FINALIZED_SLOT,
    62→      blockSlot: blockHeader.slot,
    63→      finalizedSlot,
    64→    });
    65→  }
    66→
    67→  // 6) [IGNORE] The sidecar's block's parent (defined by block_header.parent_root) has been seen (via gossip
    68→  //             or non-gossip sources)
    69→  const parentRoot = toRootHex(blockHeader.parentRoot);
    70→  const parentBlock = chain.forkChoice.getBlockHex(parentRoot);
    71→  if (parentBlock === null) {
    72→    // If fork choice does *not* consider the parent to be a descendant of the finalized block,
    73→    // then there are two more cases:
    74→    //
    75→    // 1. We have the parent stored in our database. Because fork-choice has confirmed the
    76→    //    parent is *not* in our post-finalization DAG, all other blocks must be either
    77→    //    pre-finalization or conflicting with finalization.
    78→    // 2. The parent is unknown to us, we probably want to download it since it might actually
    79→    //    descend from the finalized root.
    80→    // (Non-Lighthouse): Since we prune all blocks non-descendant from finalized checking the `db.block` database won't be useful to guard
    81→    // against known bad fork blocks, so we throw PARENT_UNKNOWN for cases (1) and (2)
    82→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    83→      code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
    84→      parentRoot,
    85→    });
    86→  }
    87→
    88→  // 8) [REJECT] The sidecar is from a higher slot than the sidecar's block's parent
    89→  if (parentBlock.slot >= blockHeader.slot) {
    90→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    91→      code: DataColumnSidecarErrorCode.NOT_LATER_THAN_PARENT,
    92→      parentSlot: parentBlock.slot,
    93→      slot: blockHeader.slot,
    94→    });
    95→  }
    96→
    97→  // getBlockSlotState also checks for whether the current finalized checkpoint is an ancestor of the block.
    98→  // As a result, we throw an IGNORE (whereas the spec says we should REJECT for this scenario).
    99→  // this is something we should change this in the future to make the code airtight to the spec.
   100→  // 7) [REJECT] The sidecar's block's parent passes validation.
   101→  const blockState = await chain.regen
   102→    .getBlockSlotState(parentRoot, blockHeader.slot, {dontTransferCache: true}, RegenCaller.validateGossipDataColumn)
   103→    .catch(() => {
   104→      throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
   105→        code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
   106→        parentRoot,
   107→      });
   108→    });
